//! `odx.lock`: the resolved commits of every merge and package.
//!
//! The file is TOML with a `version` key. It is written only by odx, always
//! in the same layout, so that locking twice without upstream changes
//! produces a byte-identical file:
//!
//! ```toml
//! # Generated by odx. Do not edit.
//! version = 1
//!
//! [odoo]
//! url = "https://github.com/OCA/OCB.git"
//! rev = "<sha>"
//!
//! [[repositories]]
//! name = "pos"
//! url = "https://github.com/OCA/pos.git"
//! base = "17.0"
//! base_sha = "<sha>"
//! result_tree = "<tree>"
//!
//! [[repositories.merges]]
//! source = { pr = 123 }
//! sha = "<sha>"
//! tree = "<tree>"
//! patch_id = "<patch-id>"
//! status = "merged"
//!
//! [packages.odoo-addon-pos-vouchers]
//! url = "https://github.com/OCA/pos.git"
//! source = { pr = 45 }
//! sha = "<sha>"
//! ```

use std::collections::BTreeMap;

use serde::Deserialize;
use toml_edit::{ArrayOfTables, DocumentMut, InlineTable, Item, Table, Value};

use crate::schema::Merge;

/// The lockfile format this version of odx reads and writes.
pub const LOCK_VERSION: u32 = 1;

const HEADER: &str = "# Generated by odx. Do not edit.\n";

/// Errors from reading `odx.lock`.
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum LockError {
    /// The file is not valid TOML or does not match the format.
    #[error("{0}")]
    Format(String),
    /// The file was written by a newer odx.
    #[error("odx.lock has version {found}; this odx reads version {LOCK_VERSION}, upgrade odx")]
    Newer {
        /// The version in the file.
        found: u32,
    },
    /// The file uses a format that is no longer read directly.
    #[error("odx.lock has version {found}; run `odx lock --migrate`")]
    Older {
        /// The version in the file.
        found: u32,
    },
    /// The file has a version no odx release wrote.
    #[error("odx.lock has version {found}, which no odx release wrote")]
    Unknown {
        /// The version in the file.
        found: u32,
    },
    /// A commit, tree or patch id is not a hexadecimal object id.
    #[error("{key}: {value:?} is not a hexadecimal object id")]
    BadObjectId {
        /// Where the value is.
        key: String,
        /// The value.
        value: String,
    },
}

/// The configured source of a locked merge or package.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LockSource {
    /// Pull request number.
    pub pr: Option<u32>,
    /// Configured commit (possibly abbreviated).
    pub sha: Option<String>,
    /// Branch.
    pub branch: Option<String>,
    /// Remote of the branch, when not the repository URL.
    pub remote: Option<String>,
    /// Tag (packages).
    pub tag: Option<String>,
}

impl LockSource {
    /// The lock source of a configured merge.
    pub fn of(merge: &Merge) -> Self {
        Self {
            pr: merge.pr,
            sha: merge.sha.clone(),
            branch: merge.branch.clone(),
            remote: merge.remote.clone(),
            tag: None,
        }
    }

    /// Whether this is the source of `merge`.
    pub fn matches(&self, merge: &Merge) -> bool {
        *self == Self::of(merge)
    }
}

/// What happened to a merge at lock time.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum MergeStatus {
    /// Merged into the target branch.
    Merged,
    /// Skipped by its `on_conflict = "skip"` policy.
    Skipped,
    /// Kept at an earlier commit by the guard rail.
    Pinned,
}

/// CI state of an upstream pull request head.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum CiState {
    /// All required checks passed.
    Green,
    /// A check failed.
    Red,
    /// Checks are still running.
    Pending,
    /// The forge reports no checks.
    Unknown,
}

impl MergeStatus {
    /// The status as written in the lockfile.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Merged => "merged",
            Self::Skipped => "skipped",
            Self::Pinned => "pinned",
        }
    }
}

impl CiState {
    /// The state as written in the lockfile.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Green => "green",
            Self::Red => "red",
            Self::Pending => "pending",
            Self::Unknown => "unknown",
        }
    }
}

/// Why an upstream head is red.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Deserialize)]
#[serde(rename_all = "kebab-case")]
pub enum RedClassification {
    /// Failing checks relate to the changed files.
    Red,
    /// The base branch fails the same checks.
    BaseAlsoFailing,
    /// The failing checks belong to another addon.
    OtherAddon,
}

impl RedClassification {
    /// The classification as written in the lockfile.
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Red => "red",
            Self::BaseAlsoFailing => "base-also-failing",
            Self::OtherAddon => "other-addon",
        }
    }
}

/// A locked merge.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LockedMerge {
    /// The configured source.
    pub source: LockSource,
    /// The resolved commit.
    pub sha: String,
    /// Tree of the resolved commit.
    pub tree: String,
    /// `git patch-id --stable` of the merge's changes.
    pub patch_id: String,
    /// Ref of the commit in the private vault, if pushed.
    pub mirror_ref: Option<String>,
    /// What happened at lock time.
    pub status: MergeStatus,
    /// Newer upstream head that was not adopted.
    pub upstream_head: Option<String>,
    /// CI state of `upstream_head`.
    pub upstream_head_ci: Option<CiState>,
    /// Why `upstream_head` is red.
    pub upstream_head_classification: Option<RedClassification>,
    /// Date (`YYYY-MM-DD`) since which the merge is pinned.
    pub pinned_since: Option<String>,
}

/// A locked repository.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LockedRepository {
    /// Repository name.
    pub name: String,
    /// Repository URL.
    pub url: String,
    /// Base branch.
    pub base: String,
    /// Resolved base commit.
    pub base_sha: String,
    /// Tree of the aggregated result.
    pub result_tree: String,
    /// Merges in configuration order.
    #[serde(default)]
    pub merges: Vec<LockedMerge>,
}

/// A locked package.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct LockedPackage {
    /// Dependency group.
    pub group: Option<String>,
    /// Repository URL.
    pub url: String,
    /// The configured source.
    pub source: LockSource,
    /// Subdirectory of the addon.
    pub subdirectory: Option<String>,
    /// The resolved commit.
    pub sha: String,
    /// Ref of the commit in the private vault, if pushed.
    pub mirror_ref: Option<String>,
}

/// The Odoo core revision, when Odoo is a git source.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct OdooPin {
    /// Repository URL.
    pub url: String,
    /// Resolved commit.
    pub rev: String,
}

/// The contents of `odx.lock`; the default is an empty lockfile of the
/// current version.
#[derive(Debug, Clone, PartialEq, Eq, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Lockfile {
    /// Format version; [`LOCK_VERSION`] after parsing.
    pub version: u32,
    /// The Odoo core revision.
    pub odoo: Option<OdooPin>,
    /// Locked repositories, sorted by name when written.
    #[serde(default)]
    pub repositories: Vec<LockedRepository>,
    /// Locked packages by distribution name.
    #[serde(default)]
    pub packages: BTreeMap<String, LockedPackage>,
}

#[derive(Deserialize)]
struct VersionOnly {
    version: Option<u32>,
}

fn is_object_id(text: &str) -> bool {
    matches!(text.len(), 40 | 64) && text.bytes().all(|b| b.is_ascii_hexdigit())
}

impl Default for Lockfile {
    fn default() -> Self {
        Self {
            version: LOCK_VERSION,
            odoo: None,
            repositories: Vec::new(),
            packages: BTreeMap::new(),
        }
    }
}

impl Lockfile {
    /// An empty lockfile of the current version.
    pub fn new() -> Self {
        Self::default()
    }

    /// Parse `odx.lock` text.
    ///
    /// # Errors
    ///
    /// [`LockError::Newer`] / [`LockError::Older`] for other format
    /// versions, [`LockError::Format`] for anything that does not match the
    /// format, [`LockError::BadObjectId`] for malformed commits and trees.
    pub fn parse(text: &str) -> Result<Self, LockError> {
        let format = |e: toml::de::Error| LockError::Format(e.to_string());
        let found = toml::from_str::<VersionOnly>(text)
            .map_err(format)?
            .version
            .ok_or_else(|| LockError::Format("odx.lock has no `version`".to_owned()))?;
        match found.cmp(&LOCK_VERSION) {
            std::cmp::Ordering::Greater => return Err(LockError::Newer { found }),
            std::cmp::Ordering::Less => return Err(LockError::Older { found }),
            std::cmp::Ordering::Equal => {}
        }
        let lock: Self = toml::from_str(text).map_err(format)?;
        lock.check_object_ids()?;
        Ok(lock)
    }

    /// Read `odx.lock` text written by any odx and return it in the current
    /// format. Version 1 is the first format, so for now this reads it as
    /// [`Lockfile::parse`] does; formats that change later are converted
    /// here.
    ///
    /// ```
    /// use odx_config::lock::Lockfile;
    ///
    /// let lock = Lockfile::migrate("version = 1\n").unwrap();
    /// assert_eq!(lock, Lockfile::new());
    /// assert!(Lockfile::migrate("version = 0\n").is_err());
    /// ```
    ///
    /// # Errors
    ///
    /// [`LockError::Unknown`] for a version no odx wrote, and the errors
    /// of [`Lockfile::parse`].
    pub fn migrate(text: &str) -> Result<Self, LockError> {
        match Self::parse(text) {
            Err(LockError::Older { found }) => Err(LockError::Unknown { found }),
            other => other,
        }
    }

    fn check_object_ids(&self) -> Result<(), LockError> {
        let mut ids: Vec<(String, &str)> = Vec::new();
        if let Some(odoo) = &self.odoo {
            ids.push(("odoo.rev".to_owned(), &odoo.rev));
        }
        for repo in &self.repositories {
            let key = format!("repositories.{}", repo.name);
            ids.push((format!("{key}.base_sha"), &repo.base_sha));
            ids.push((format!("{key}.result_tree"), &repo.result_tree));
            for (i, merge) in repo.merges.iter().enumerate() {
                let key = format!("{key}.merges[{i}]");
                ids.push((format!("{key}.sha"), &merge.sha));
                ids.push((format!("{key}.tree"), &merge.tree));
                ids.push((format!("{key}.patch_id"), &merge.patch_id));
                if let Some(head) = &merge.upstream_head {
                    ids.push((format!("{key}.upstream_head"), head));
                }
            }
        }
        for (name, package) in &self.packages {
            ids.push((format!("packages.{name}.sha"), &package.sha));
        }
        match ids.into_iter().find(|(_, value)| !is_object_id(value)) {
            Some((key, value)) => Err(LockError::BadObjectId {
                key,
                value: value.to_owned(),
            }),
            None => Ok(()),
        }
    }

    /// Remove the locked merge `source` of the repository at `url` (matched
    /// across URL spellings); returns whether one was removed.
    pub fn remove_merge(&mut self, url: &str, source: &LockSource) -> bool {
        let key = crate::edit::repo_key(url);
        self.repositories
            .iter_mut()
            .filter(|repo| crate::edit::repo_key(&repo.url) == key)
            .fold(false, |removed, repo| {
                let before = repo.merges.len();
                repo.merges.retain(|merge| merge.source != *source);
                removed | (repo.merges.len() != before)
            })
    }

    /// Remove locked package `dist` (PEP 503 name comparison); returns
    /// whether it was present.
    pub fn remove_package(&mut self, dist: &str) -> bool {
        let wanted = crate::deps::normalize_name(dist);
        let before = self.packages.len();
        self.packages
            .retain(|name, _| crate::deps::normalize_name(name) != wanted);
        self.packages.len() != before
    }

    /// Render the lockfile in its canonical layout.
    pub fn render(&self) -> String {
        let mut doc = DocumentMut::new();
        doc.insert("version", Item::Value(Value::from(i64::from(LOCK_VERSION))));
        if let Some(odoo) = &self.odoo {
            let mut table = Table::new();
            set(&mut table, "url", Some(&odoo.url));
            set(&mut table, "rev", Some(&odoo.rev));
            doc.insert("odoo", Item::Table(table));
        }
        if !self.repositories.is_empty() {
            let mut repos: Vec<&LockedRepository> = self.repositories.iter().collect();
            repos.sort_by(|a, b| a.name.cmp(&b.name).then_with(|| a.url.cmp(&b.url)));
            let mut tables = ArrayOfTables::new();
            for repo in repos {
                tables.push(repository_table(repo));
            }
            doc.insert("repositories", Item::ArrayOfTables(tables));
        }
        if !self.packages.is_empty() {
            let mut packages = Table::new();
            packages.set_implicit(true);
            for (name, package) in &self.packages {
                packages.insert(name, Item::Table(package_table(package)));
            }
            doc.insert("packages", Item::Table(packages));
        }
        format!("{HEADER}{doc}")
    }
}

fn set(table: &mut Table, key: &str, value: Option<&String>) {
    if let Some(value) = value {
        table.insert(key, Item::Value(Value::from(value.as_str())));
    }
}

fn source_value(source: &LockSource) -> Item {
    let mut table = InlineTable::new();
    if let Some(pr) = source.pr {
        table.insert("pr", Value::from(i64::from(pr)));
    }
    for (key, value) in [
        ("sha", &source.sha),
        ("branch", &source.branch),
        ("tag", &source.tag),
        ("remote", &source.remote),
    ] {
        if let Some(value) = value {
            table.insert(key, Value::from(value.as_str()));
        }
    }
    Item::Value(Value::InlineTable(table))
}

fn repository_table(repo: &LockedRepository) -> Table {
    let mut table = Table::new();
    set(&mut table, "name", Some(&repo.name));
    set(&mut table, "url", Some(&repo.url));
    set(&mut table, "base", Some(&repo.base));
    set(&mut table, "base_sha", Some(&repo.base_sha));
    set(&mut table, "result_tree", Some(&repo.result_tree));
    if !repo.merges.is_empty() {
        let mut merges = ArrayOfTables::new();
        for merge in &repo.merges {
            let mut entry = Table::new();
            entry.insert("source", source_value(&merge.source));
            set(&mut entry, "sha", Some(&merge.sha));
            set(&mut entry, "tree", Some(&merge.tree));
            set(&mut entry, "patch_id", Some(&merge.patch_id));
            set(&mut entry, "mirror_ref", merge.mirror_ref.as_ref());
            entry.insert("status", Item::Value(Value::from(merge.status.as_str())));
            set(&mut entry, "upstream_head", merge.upstream_head.as_ref());
            for (key, value) in [
                (
                    "upstream_head_ci",
                    merge.upstream_head_ci.map(CiState::as_str),
                ),
                (
                    "upstream_head_classification",
                    merge
                        .upstream_head_classification
                        .map(RedClassification::as_str),
                ),
            ] {
                if let Some(value) = value {
                    entry.insert(key, Item::Value(Value::from(value)));
                }
            }
            set(&mut entry, "pinned_since", merge.pinned_since.as_ref());
            merges.push(entry);
        }
        table.insert("merges", Item::ArrayOfTables(merges));
    }
    table
}

fn package_table(package: &LockedPackage) -> Table {
    let mut table = Table::new();
    set(&mut table, "group", package.group.as_ref());
    set(&mut table, "url", Some(&package.url));
    table.insert("source", source_value(&package.source));
    set(&mut table, "subdirectory", package.subdirectory.as_ref());
    set(&mut table, "sha", Some(&package.sha));
    set(&mut table, "mirror_ref", package.mirror_ref.as_ref());
    table
}

